import requests
queries=['circumflex chronic total occlusions procedural outcomes','circumflex CTO multicentre US registry','percutaneous intervention circumflex chronic total occlusion']
for q in queries:
 print('\nQUERY',q)
 try:
  data=requests.get('https://api.crossref.org/works',params={'query.bibliographic':q,'rows':20},timeout=30).json()
  for x in data.get('message',{}).get('items',[]):
   title=' '.join(x.get('title',[]))
   if any(w in title.lower() for w in ['circumflex','chronic total','cto']):
    print(x.get('DOI'),title,x.get('container-title'),x.get('published-print') or x.get('published-online'),x.get('author',[{}])[0].get('family'))
 except Exception as e: print('ERR',e)

import requests, json
urls=[
 'https://www.ebi.ac.uk/europepmc/webservices/rest/search',
 'https://www.ncbi.nlm.nih.gov/research/bionlp/RESTful/pubmed.cgi/BioC_json/PMC',
]
params={'query':'DOI:"10.1016/j.cjca.2014.07.007"','format':'json','pageSize':10}
r=requests.get(urls[0],params=params,timeout=30)
print('status',r.status_code)
data=r.json()
for x in data.get('resultList',{}).get('result',[]): print(json.dumps(x,indent=2))
for q in ['EXT_ID:10.1016/j.cjca.2014.07.007','TITLE:"Percutaneous Intervention of Circumflex Chronic Total Occlusions"']:
 r=requests.get(urls[0],params={'query':q,'format':'json','pageSize':10},timeout=30)
 print('\n',q,r.status_code)
 for x in r.json().get('resultList',{}).get('result',[]): print(json.dumps(x,indent=2))
